"""Policy for agent_0 -- blind ground robot, guided by agent_1 (aerial).

I have no pose, no map, no goal (all null) and zero sensing radius.
agent_1 sees everything including my own pose, and streams guide_cmd
messages at ~10Hz: body-frame velocity already computed for MY heading,
so I never need to know theta myself. Protocol (agent_1's proposal,
adopted as-is):

  {"type": "guide_cmd", "v": 1, "seq": int, "t_sent": <their t_sim>,
   "target": "agent_0", "cmd_body": {"vx","vy","omega"},
   "mode": "drive"|"stop"|"hold_goal", "goal_info": {...}}

t_sent is agent_1's t_sim, which the harness note says shares my clock,
so freshness = my_obs.t_sim - t_sent. Fail closed: no message yet, stale
(>1.0s), unparseable, or mode == "stop" -> publish zero. I ack every
guide_cmd I accept so agent_1 has liveness feedback.
"""

from skills import comms, safety

STALE_S = 1.0


def on_start(ctx):
    ctx.state["observation"] = None
    ctx.state["last_cmd"] = None  # {"t_sent","seq","cmd_body","mode"}
    ctx.state["n_guide_total"] = 0
    ctx.state["n_guide_rejected"] = 0
    ctx.log("agent_0: receiver active, still fail-closed until a fresh guide_cmd is read")


def on_observation(ctx, observation):
    ctx.state["observation"] = observation


def _parse_guide_cmd(payload):
    if not isinstance(payload, dict):
        return None
    if payload.get("type") != "guide_cmd":
        return None
    target = payload.get("target")
    if target not in (None, "agent_0"):
        return None
    cmd_body = payload.get("cmd_body")
    t_sent = payload.get("t_sent")
    if not isinstance(cmd_body, dict) or not isinstance(t_sent, (int, float)):
        return None
    try:
        vx = float(cmd_body.get("vx", 0.0))
        vy = float(cmd_body.get("vy", 0.0))
        omega = float(cmd_body.get("omega", 0.0))
    except (TypeError, ValueError):
        return None
    return {
        "t_sent": float(t_sent),
        "seq": payload.get("seq"),
        "cmd_body": {"vx": vx, "vy": vy, "omega": omega},
        "mode": payload.get("mode"),
    }


def on_inbox(ctx, message):
    payload = comms.payload_of(message)
    sender = comms.sender_of(message)
    parsed = _parse_guide_cmd(payload)
    if parsed is None:
        return
    ctx.state["n_guide_total"] = ctx.state.get("n_guide_total", 0) + 1
    prev = ctx.state.get("last_cmd")
    if prev is not None and parsed.get("seq") is not None and prev.get("seq") is not None:
        if parsed["seq"] <= prev["seq"]:
            return  # out-of-order/duplicate, ignore
    ctx.state["last_cmd"] = parsed
    if sender is not None:
        ctx.send_message({"type": "ack", "v": 1, "seq_rx": parsed.get("seq")}, recipient=sender)


def on_tick(ctx):
    obs = ctx.state.get("observation")
    last_cmd = ctx.state.get("last_cmd")

    action = {"vx": 0.0, "vy": 0.0, "omega": 0.0}
    status_mode = "no_observation"
    age_s = None

    if obs is not None:
        t_sim = obs.get("t_sim")
        if last_cmd is None:
            status_mode = "waiting_first_cmd"
        elif not isinstance(t_sim, (int, float)):
            status_mode = "no_tsim"
        else:
            age_s = t_sim - last_cmd["t_sent"]
            if age_s < 0 or age_s > STALE_S:
                status_mode = "stale"
            elif last_cmd.get("mode") == "stop":
                status_mode = "guide_stop"
            else:
                status_mode = "driving"
                action = dict(last_cmd["cmd_body"])

        # red-light freeze only (no pose needed); collision_reflex needs
        # vertices we do not have, so it is intentionally not used here.
        action = safety.red_light_guard(obs, action)

    action = safety.clamp(action)
    ctx.publish_action(action)

    ctx.status(
        {
            "mode": status_mode,
            "age_s": None if age_s is None else round(age_s, 3),
            "last_seq": (last_cmd or {}).get("seq"),
            "n_guide_total": ctx.state.get("n_guide_total", 0),
            "published": action,
        }
    )
